#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench definitions (NI, NJ, NK, NL, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / Expr(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / Expr(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / Expr(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / Expr(nk);

    // Simple schedules; this runs once and is outside the timed region.
    Target t = get_host_target();
    int vec = t.natural_vector_size(type_of<num_t>());
    if (vec <= 0) vec = 1;

    init_A
        .reorder(k, i)           // contiguous over k
        .vectorize(k, vec)
        .parallel(i);
    init_B
        .reorder(j, k)
        .vectorize(j, vec)
        .parallel(k);
    init_C
        .reorder(l, j)
        .vectorize(l, vec)
        .parallel(j);
    init_D
        .reorder(l, i)
        .vectorize(l, vec)
        .parallel(i);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // allocated but not used directly by the pipeline

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j) {
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //
    //   for (i)
    //     for (l) {          // 'l' is column index of D/C
    //       D[i][l] *= beta;
    //       for (k)
    //         D[i][l] += tmp[i][k] * C[k][l];
    //     }
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp (first dimension)
    //   l -> column index for D   (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Good cache locality for both GEMMs.
    //  - Parallelize across rows of the result (i).
    //  - Vectorize along the contiguous dimension (l for D, j for tmp).
    //  - Avoid materializing the full tmp; compute only the rows that
    //    are needed for the current row of D (better locality and less memory).
    //
    // Strategy:
    //  - Compute D_func at root, parallel over 'i', vectorize over 'l'.
    //  - Compute each row of tmp_func at the loop over 'i' in D_func,
    //    so only a single row of tmp is stored at a time (Halide will
    //    fold the storage in the i-dimension).
    //  - Vectorize tmp_func along 'j' so we get vectorized loads/stores
    //    for tmp and B.
    // ------------------------------------------------------------------------

    Target target = get_host_target();
    int vec = target.natural_vector_size(type_of<num_t>());
    if (vec <= 0) vec = 1;

    Var lo("lo"), li("li");   // for splitting l
    Var jo("jo"), ji("ji");   // for splitting j

    // ----- Schedule for D_func (final result) -----
    D_func.compute_root();

    // Make l (the column dimension) innermost and vectorize it.
    // Loop nest (pure stage) becomes roughly:
    //   for i (parallel)
    //     for lo
    //       for li (vectorized over l)
    D_func
        .reorder(l, i)
        .split(l, lo, li, vec)
        .parallel(i)
        .vectorize(li);

    // Update stage has the reduction over k_DC; we keep k_DC innermost
    // over each vector of l.
    // Loop nest (update stage) becomes roughly:
    //   for i (parallel)
    //     for lo
    //       for li (vectorized over l)
    //         for k_DC
    D_func.update()
        .reorder(k_DC, l, i)
        .split(l, lo, li, vec)
        .parallel(i)
        .vectorize(li);

    // ----- Schedule for tmp_func (intermediate GEMM) -----
    //
    // We compute each row tmp(i, :) just before it is used by the
    // corresponding row of D. This improves locality and lets Halide
    // fold tmp storage along i, so only one row is kept live at a time.
    tmp_func
        .compute_at(D_func, i)  // per-row of D
        .reorder(j, i);         // j is innermost, contiguous

    // Vectorize tmp over j (the contiguous dimension).
    tmp_func
        .split(j, jo, ji, vec)
        .vectorize(ji);

    // Update stage: iterate over k_AB for each j, i.
    // We reorder so that j is innermost and vectorized, and k_AB is next.
    // Loop nest (update stage) becomes roughly:
    //   for this i (inside D's loop, possibly in parallel)
    //     for jo
    //       for ji (vectorized over j)
    //         for k_AB
    tmp_func.update()
        .reorder(j, k_AB, i)
        .split(j, jo, ji, vec)
        .vectorize(ji);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D (in place, using D_param as input)
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
