// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    // -------------------------
    // Scheduling for init_*()
    // -------------------------
    //
    // These initializations are embarrassingly parallel and have
    // straightforward, unit-stride access in their inner loops.
    // We parallelize over the outer (row) dimension and vectorize
    // over the inner (contiguous) dimension.

    Target init_target = get_jit_target_from_environment();
    const int vec_width = std::max(4, init_target.natural_vector_size(type_of<num_t>()));

    // A(k, i): i outer, k inner (contiguous)
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(k, vec_width);

    // B(j, k): k outer, j inner (contiguous)
    init_B
        .compute_root()
        .parallel(k)
        .vectorize(j, vec_width);

    // C(l, j): j outer, l inner (contiguous)
    init_C
        .compute_root()
        .parallel(j)
        .vectorize(l, vec_width);

    // D(l, i): i outer, l inner (contiguous)
    init_D
        .compute_root()
        .parallel(i)
        .vectorize(l, vec_width);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // used only as realization target for tmp_func

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Optimized scheduling
    //
    // Goals:
    //   * Good cache locality:
    //       - Compute one row of tmp(i, :) at a time and immediately
    //         consume it to update D(i, :), so tmp stays hot in cache.
    //   * Parallelism:
    //       - Different rows i are independent, so parallelize over i.
    //   * Vectorization:
    //       - j and l are unit-stride dimensions; vectorize across them.
    //   * Avoid storing full tmp[ni][nj] at once; use a row buffer
    //     per row i (and per worker thread).
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = std::max(4, target.natural_vector_size(type_of<num_t>()));

    // Final result D_func is computed at root.
    D_func.compute_root();

    // Pure stage of D: D(l, i) = beta * D_param(l, i)
    // Memory layout of D is D(l, i) with l (columns) contiguous,
    // so inner loop over l is ideal for vectorization.
    D_func
        .reorder(l, i)          // i outer, l inner (default for (l, i), but explicit for clarity)
        .vectorize(l, vec_width)
        .parallel(i);           // parallelize across rows

    // Update stage of D: accumulation over k_DC
    // We keep the reduction loop innermost and still vectorize across l.
    D_func.update()
        .reorder(k_DC, l, i)    // i outer, l middle, k_DC inner
        .vectorize(l, vec_width)
        .parallel(i);

    // tmp_func is a row-wise temporary:
    // for each i, we need all tmp(j, i) over j, but tmp(i, :) is never
    // reused for a different i. We therefore compute tmp inside the
    // loop over i of D_func to:
    //   * Keep tmp(i, :) in cache while updating D(i, :)
    //   * Only allocate storage for a single row of tmp (per thread)
    //
    // This preserves the mathematical reduction order over k_AB for each
    // tmp(j, i) (we only change the schedule of when each row i is computed).
    tmp_func
        .compute_at(D_func, i)  // compute one full row tmp(:, i) whenever D processes row i
        .reorder(j, i);         // i outer, j inner (j contiguous)

    // Pure initialization of tmp: tmp(j, i) = 0
    tmp_func
        .vectorize(j, vec_width);

    // Update of tmp: accumulation over k_AB
    // We keep the reduction variable innermost and vectorize across j,
    // the contiguous dimension. Loop nesting conceptually:
    //   for i
    //     for k_AB
    //       for j (vectorized)
    tmp_func.update()
        .reorder(j, k_AB, i)    // innermost j (contiguous & vectorized), then k_AB, then i
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
