 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    // Simple, cache-friendly schedules for initialization. These are not
    // included in the timed kernel, but make initialization reasonably fast.
    const int vec = 8;  // Safe default; can be tuned per-target.

    init_A
        .compute_root()
        .reorder(k, i)
        .parallel(i)
        .vectorize(k, vec);

    init_B
        .compute_root()
        .reorder(j, k)
        .parallel(k)
        .vectorize(j, vec);

    init_C
        .compute_root()
        .reorder(l, j)
        .parallel(j)
        .vectorize(l, vec);

    init_D
        .compute_root()
        .reorder(l, i)
        .parallel(i)
        .vectorize(l, vec);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // used only as internal storage

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j) {
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //
    //   for (i)
    //     for (l) {
    //       D[i][l] *= beta;
    //       for (j)
    //         D[i][l] += tmp[i][j] * C[j][l];
    //     }
    //
    // Mapping to Halide coordinates and buffer layouts:
    //
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension of tmp, reduction
    //        dimension in D's second phase)
    //   k -> reduction index over nk for tmp
    //   l -> column index in D (first dimension of D and C)
    //
    // Buffers:
    //   tmp(j, i)       corresponds to tmp[i][j]
    //   A_param(k, i)   corresponds to A[i][k]
    //   B_param(j, k)   corresponds to B[k][j]
    //   C_param(l, j)   corresponds to C[j][l]
    //   D_param(l, i)   corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // First GEMM: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
    // Represented as tmp(j, i).
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // Second GEMM and accumulation into D:
    // D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
    // Represented as D(l, i).
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //   * Reduce memory footprint by not storing the full tmp[ni][nj] at once.
    //   * Improve data locality and memory access patterns:
    //       - When forming tmp, we want innermost loops over j so that
    //         B(j,k) and tmp(j,i) are accessed contiguously.
    //       - When forming D, we want innermost loops over l so that
    //         C(l,j) and D(l,i) are accessed contiguously.
    //   * Exploit parallelism over independent rows (i dimension).
    //   * Vectorize over the fast-varying x dimension (j or l).
    //
    // Strategy:
    //   * Compute D_func at root (final output).
    //   * Compute tmp_func at each 'i' of D_func (compute_at). This
    //     reproduces the original algorithmic structure:
    //       for i:
    //         compute full row tmp[i][*]
    //         use that row to update D[i][*]
    //     but allows Halide to allocate only a row (or a small circular
    //     buffer) for tmp, rather than ni*nj elements.
    //   * Parallelize the outer loop over i in D_func.
    //   * Vectorize j in tmp_func and l in D_func.
    // ------------------------------------------------------------------------

    const int vec = 8;  // Vector width to use on the fast (x) dimension.

    // 1. Schedule D (final output)
    // Pure stage: D(l, i) = beta * D_param(l, i)
    D_func
        .compute_root()
        // Make l (column) the innermost pure variable: row-major traversal
        // over D, parallelized across rows (i).
        .reorder(l, i)
        .parallel(i)
        .vectorize(l, vec);

    // Update stage: D(l, i) += tmp(k_DC, i) * C(l, k_DC)
    D_func.update()
        // Order loops as: for i (parallel) { for k_DC { for l { ... } } }
        // so that l is innermost and contiguous in memory for D and C.
        .reorder(l, k_DC, i)
        .parallel(i)
        .vectorize(l, vec);

    // 2. Schedule tmp as a producer of D
    //
    // Compute each row of tmp inside the loop over i of D_func. This way,
    // only one row of tmp is materialized at a time, and it is immediately
    // consumed by the D update. Halide will automatically fold storage for
    // tmp along the i dimension into a small circular buffer.
    tmp_func
        .compute_at(D_func, i)
        // Make j (column of tmp / column of B) innermost so that both
        // tmp(j, i) and B(j, k_AB) are accessed contiguously.
        .reorder(j, i)
        .vectorize(j, vec);

    // Update of tmp: tmp(j, i) += alpha * A(k_AB, i) * B(j, k_AB)
    tmp_func.update()
        // Loop order for the reduction:
        //   for k_AB        (over nk)
        //     for j (vec)   (over nj)
        // This matches the efficient i-k-j ordering of the original C code:
        //   - A(k_AB, i) is reused across the inner j loop.
        //   - B(j, k_AB) and tmp(j, i) are accessed contiguously in j.
        .reorder(j, k_AB, i)
        .vectorize(j, vec);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
