    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // First GEMM: tmp(i,j) = alpha * A(i, :) * B(:, j)
    // Stored as tmp(j, i) to match buffer layout.
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += alpha_expr * A_param(k_AB, i) * B_param(j, k_AB);

    // Second GEMM and accumulation with beta*D:
    // D(i,l) = beta * D(i,l) + tmp(i,:) * C(:,l)
    // Stored as D(l, i).
    D_func(l, i) = beta_expr * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling for performance
    //
    // Goals:
    //   * Parallelize across output rows (i) to exploit many cores.
    //   * Vectorize across the fast-varying dimension (l for D, j for tmp)
    //     to utilize SIMD.
    //   * Improve locality by computing each row of tmp on demand inside
    //     the corresponding row of D, instead of materializing full tmp.
    //
    // Data layout:
    //   * For D and C, the first dimension (l) is contiguous. Vectorizing
    //     across l gives unit-stride loads/stores for D and C.
    //   * For tmp, the first dimension (j) is contiguous, so we vectorize in j.
    //   * A is laid out with k contiguous, which is ideal for the reduction
    //     over k_AB.
    // ------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Compute the final result at root.
    // Order dimensions as (l, i):
    //   - parallel(i): distribute rows across threads
    //   - vectorize(l): operate on several columns at once, unit stride
    D_func
        .compute_root()
        .reorder(l, i)
        .parallel(i)
        .vectorize(l, vec_width);

    // Schedule the reduction (update) of D in the same loop order.
    D_func.update()
        .reorder(k_DC, l, i)
        .parallel(i)
        .vectorize(l, vec_width);

    // Compute one full row of tmp for each row i of D, just before it
    // is needed. This avoids storing the full tmp[ni][nj] matrix and
    // improves temporal locality between tmp and its use in D.
    //
    // For each fixed i:
    //   tmp(j, i) is computed for all j (0..nj-1), then reused for all l.
    tmp_func
        .compute_at(D_func, i)   // inside the 'i' loop of D
        .reorder(j, i)
        .vectorize(j, vec_width);

    tmp_func.update()
        .reorder(k_AB, j, i)
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D, target);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
